import {controller, target} from '@github/catalyst'
import {verifiedFetch} from '@github-ui/verified-fetch'
import {updateUrl} from '@github-ui/history'

// Handles the inline overage budget edit dialog on the Copilot settings page.
// Submits budget create/update requests to the existing billing budgets API.
@controller('copilot-overage-budget')
export class CopilotOverageBudgetElement extends HTMLElement {
  @target declare form: HTMLFormElement
  @target declare errorMessage: HTMLElement

  connectedCallback() {
    const url = new URL(window.location.href, window.location.origin)
    if (url.searchParams.has('budget_updated')) {
      url.searchParams.delete('budget_updated')
      updateUrl(url.toString())
    }
  }

  get budgetsUrl(): string {
    return this.getAttribute('data-budgets-url') || '/settings/billing/budgets'
  }

  get customerId(): string {
    return this.getAttribute('data-customer-id') || ''
  }

  get budgetUuid(): string {
    return this.getAttribute('data-budget-uuid') || ''
  }

  get pricingTargetId(): string {
    return this.getAttribute('data-pricing-target-id') || ''
  }

  async submit(event?: Event) {
    event?.preventDefault()

    const budgetAmount = this.form.querySelector<HTMLInputElement>('[name="budget_amount"]')?.value || '0'

    const body = {
      targetType: 'CustomerResource',
      targetId: this.customerId,
      pricingTargetType: 'BundlePricing',
      pricingTargetId: this.pricingTargetId,
      targetAmount: Number(budgetAmount),
      budgetLimitType: 'PreventFurtherUsage',
      alertEnabled: false,
      alertRecipientUserIds: [] as string[],
      licenseCount: 0,
      uuid: this.budgetUuid,
    }

    const isUpdate = this.budgetUuid !== ''
    const url = isUpdate ? `${this.budgetsUrl}/${this.budgetUuid}` : this.budgetsUrl
    const method = isUpdate ? 'PATCH' : 'POST'

    try {
      this.#hideError()

      const response = await verifiedFetch(url, {
        method,
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify(body),
      })

      if (response.ok) {
        const redirectUrl = new URL(window.location.href, window.location.origin)
        redirectUrl.searchParams.set('budget_updated', '1')
        window.location.assign(redirectUrl.toString())
      } else {
        let errorMessage = 'Failed to update budget. Please try again.'
        try {
          const data = await response.json()
          if (data?.error) errorMessage = data.error
        } catch {
          // use default error message
        }
        this.#showError(errorMessage)
      }
    } catch {
      this.#showError('Failed to update budget. Please try again.')
    }
  }

  #showError(message: string) {
    this.errorMessage.textContent = message
    this.errorMessage.setAttribute('role', 'alert')
    this.errorMessage.hidden = false
  }

  #hideError() {
    this.errorMessage.textContent = ''
    this.errorMessage.removeAttribute('role')
    this.errorMessage.hidden = true
  }
}
